// How many people walk each street of the detailed city, generated by tools/build-footfall.py: residents per
// cadastral block (Ajuntament de València: Illes de cases cadastrals, barri residents, CC BY 4.0; Catastro dwellings),
// workplaces (Catastro), shops, bars & restaurants (OpenStreetMap, ODbL). VLF1 (gzipped) = magic, u16 nx, u16 nz,
// f32 x0, f32 z0, f32 cell, f32 scale, then nx*nz u8 per channel (home, shop, food): people per metre of street (both
// sidewalks) at a weekday midday = value * scale. The map knows nothing of sidewalk geometry: it is sampled wherever
// the walkers are, so it survives changes to curbs and sidewalks.
let grid = null;
try {
  const response = await fetch(new URL('./vlc-footfall.bin.gz', import.meta.url));
  if (!response.ok) throw new Error(`footfall request failed: ${response.status}`);
  const body = new Uint8Array(await response.arrayBuffer());
  const data = body[0] === 0x1f && body[1] === 0x8b
    ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
    : body;
  grid = decodeFootfall(data);
} catch (error) {
  console.warn('[footfall] no footfall map, people spread evenly:', error.message);
}

function decodeFootfall(data) {
  if (String.fromCharCode(...data.subarray(0, 4)) !== 'VLF1') throw new Error('Invalid footfall data.');
  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
  const nx = view.getUint16(4, true), nz = view.getUint16(6, true);
  const n = nx * nz;
  return {
    nx, nz,
    x0: view.getFloat32(8, true), z0: view.getFloat32(12, true),
    cell: view.getFloat32(16, true), scale: view.getFloat32(20, true),
    home: data.subarray(24, 24 + n), shop: data.subarray(24 + n, 24 + 2 * n), food: data.subarray(24 + 2 * n, 24 + 3 * n)
  };
}

// Time of day by the lighting presets (js/lighting.js), as factors on the midday channels. Rules from València's
// day (no hourly counts are published): shops open 10-14 h and 17-20:30 h, lunch and dinner late, the evening walk
// (passeig) around sunset, bars busy at 23 h while the shops are shut.
//   golden   16:00 solar, ~17:30 local  afternoon shopping
//   midday   10:30 solar, ~12:30 local  the busy late morning (the reference)
//   twilight sunset, ~19:30 local       the evening walk, terraces filling
//   midnight 23:00                      bars and restaurants only
const FOOTFALL_HOURS = {
  golden: { home: 0.95, shop: 1.05, food: 0.8 },
  midday: { home: 1, shop: 1, food: 1 },
  twilight: { home: 0.9, shop: 0.85, food: 1.15 },
  midnight: { home: 0.15, shop: 0.05, food: 0.6 }
};
let hours = FOOTFALL_HOURS.golden; // the game opens at the golden hour
let hoursId = 'golden';
let version = 0; // bumps whenever the time of day changes, for the systems that cache footfall
const UNIFORM = 0.05; // people per metre without the map

function setFootfallTime(presetId) {
  const next = FOOTFALL_HOURS[presetId];
  if (!next || presetId === hoursId) return;
  hours = next;
  hoursId = presetId;
  version++;
}

// People per metre of street at (x, z) now
function footfallAt(x, z) {
  if (!grid) return UNIFORM;
  const i = Math.floor((x - grid.x0) / grid.cell), j = Math.floor((z - grid.z0) / grid.cell);
  if (i < 0 || j < 0 || i >= grid.nx || j >= grid.nz) return 0;
  const k = j * grid.nx + i;
  return (grid.home[k] * hours.home + grid.shop[k] * hours.shop + grid.food[k] * hours.food) * grid.scale;
}

const footfallVersion = () => version;
const footfallTime = () => hoursId;

export { footfallAt, setFootfallTime, footfallVersion, footfallTime, decodeFootfall, FOOTFALL_HOURS };
